from pathlib import Path
from collections import defaultdict
from openpyxl import load_workbook
from openpyxl.utils.cell import range_boundaries
import json, re, html

ROOT=Path(__file__).resolve().parent
APP_VERSION='2.7.2'
SOURCE=ROOT/'plugin_usage_semantic_hybrid_corrected.xlsx'
DIST=ROOT.parent/'current'  # готовые файлы собираются в plugin-navigator/current
OUTPUT=DIST/'Plugin_Navigator_Full.html'
DATA_OUT=ROOT/'plugin_navigator_database.json'
WIN_HTML=ROOT/'Plugin_Navigator_Windows_Source'/'resources'/'index.html'
wb=load_workbook(SOURCE,data_only=True,read_only=False)

# ---------- Read semantic catalog ----------
plugins=[]
for row in wb['Полный каталог'].iter_rows(min_row=5,values_only=True):
    if not row[2]: continue
    plugins.append({
        'id': re.sub(r'[^a-z0-9]+','-',str(row[2]).casefold()).strip('-'),
        'category':str(row[0] or ''),'family':str(row[1] or ''),'name':str(row[2]),
        'developer':str(row[3] or ''),'kind':str(row[4] or ''),'where':str(row[5] or ''),
        'description':str(row[6] or ''),'analoguesText':str(row[7] or ''),'priority':str(row[8] or ''),
        'note':str(row[9] or ''),'link':str(row[10] or '')
    })
plugin_names={p['name'] for p in plugins}
plugin_by_name={p['name']:p for p in plugins}
assert 'FabFilter Pro-Q 3' in plugin_by_name and 'FabFilter Pro-Q 4' not in plugin_by_name
_q3=plugin_by_name['FabFilter Pro-Q 3']
plugins.append({
    'id':'fabfilter-pro-q-4','category':_q3['category'],'family':_q3['family'],
    'name':'FabFilter Pro-Q 4','developer':_q3['developer'],
    'kind':'Precision EQ with dynamic, spectral and EQ Sketch',
    'where':_q3['where'],
    'description':'Следующее поколение Pro-Q: dynamic и spectral bands, EQ Sketch, Instance List. Тот же прозрачный EQ, плюс режимы только Q4.',
    'analoguesText':_q3.get('analoguesText') or '',
    'priority':'Основной',
    'note':'Новее Pro-Q 3. Spectral Dynamics и EQ Sketch — в Q4. Если сессия на Q3, это другой экземпляр.',
    'link':'https://www.fabfilter.com/products/pro-q-4-equalizer-plug-in',
})
plugin_names.add('FabFilter Pro-Q 4')
plugin_by_name['FabFilter Pro-Q 4']=plugins[-1]

# ---------- Read family overview ----------
families=[]
family_base={}
for row in wb['Семейства плагинов'].iter_rows(min_row=5,values_only=True):
    if not row[0] or not row[1]: continue
    key=str(row[0])+'||'+str(row[1])
    names=[n for n in plugin_names if plugin_by_name[n]['category']==str(row[0]) and plugin_by_name[n]['family']==str(row[1])]
    f={'key':key,'category':str(row[0]),'name':str(row[1]),'main':str(row[2] or ''),'plugins':sorted(names,key=str.casefold),
       'unites':str(row[4] or ''),'choose':str(row[5] or ''),'use':str(row[6] or ''),'position':str(row[7] or ''),'count':int(row[8] or len(names))}
    families.append(f); family_base[key]=f
for f in families:
    names=[n for n in plugin_names if plugin_by_name[n]['category']==f['category'] and plugin_by_name[n]['family']==f['name']]
    f['plugins']=sorted(names,key=str.casefold); f['count']=len(names)

# ---------- Common control/recipe profiles ----------
def C(name,role,hear,start): return {'name':name,'role':role,'hear':hear,'start':start}
def R(title,source,values,why): return {'title':title,'source':source,'values':[{'control':a,'value':b} for a,b in values],'why':why}

