def task_plan(source,available):
    s=source.casefold()
    if 'бочка' in s or 'kick' in s: wanted=['Фаза / стерео','EQ / тон','Транзиенты','Низ / фундамент','Limiter / clipper']
    elif 'snare' in s or 'малый' in s: wanted=['Gate / expander','EQ / тон','Транзиенты','Компрессия / уровень','Reverb / пространство']
    elif 'том' in s or 'перкус' in s: wanted=['Gate / expander','EQ / тон','Транзиенты','Компрессия / уровень','Reverb / пространство']
    elif 'overhead' in s: wanted=['Очистка / repair','EQ / тон','Компрессия / уровень','Сатурация / цвет','Фаза / стерео']
    elif 'drum ambience' in s or 'room microphone' in s: wanted=['EQ / тон','Компрессия / уровень','Транзиенты','Сатурация / цвет','Creative FX']
    elif 'drum bus' in s: wanted=['EQ / тон','Компрессия / уровень','Транзиенты','Сатурация / цвет','Limiter / clipper']
    elif 'бас-гитара' in s: wanted=['Фаза / стерео','EQ / тон','Компрессия / уровень','Amp / cabinet / pedal','Сатурация / цвет']
    elif '808' in s or 'synth bass' in s: wanted=['Фаза / стерео','EQ / тон','Компрессия / уровень','Низ / фундамент','Limiter / clipper']
    elif 'lead vocal' in s or 'основной вокал' in s: wanted=['Очистка / repair','EQ / тон','Компрессия / уровень','Сатурация / цвет','Reverb / пространство']
    elif 'backing vocal' in s: wanted=['EQ / тон','Компрессия / уровень','Очистка / repair','Модуляция / ширина','Reverb / пространство']
    elif 'речь' in s or 'podcast' in s or 'dialog' in s: wanted=['Очистка / repair','Channel strip / macro','Компрессия / уровень','Limiter / clipper','Контроль / анализ']
    elif 'акустичес' in s: wanted=['Очистка / repair','EQ / тон','Компрессия / уровень','Сатурация / цвет','Reverb / пространство']
    elif 'электрогитар' in s: wanted=['Gate / expander','Amp / cabinet / pedal','EQ / тон','Компрессия / уровень','Delay / echo','Reverb / пространство']
    elif 'piano' in s or 'strings' in s or 'orchestral' in s: wanted=['EQ / тон','Компрессия / уровень','Сатурация / цвет','Модуляция / ширина','Reverb / пространство']
    elif 'synth / pads' in s: wanted=['EQ / тон','Компрессия / уровень','Сатурация / цвет','Delay / echo','Reverb / пространство']
    elif 'fx / transitions' in s: wanted=['Creative FX','EQ / тон','Delay / echo','Reverb / пространство','Limiter / clipper']
    elif 'instrument bus' in s: wanted=['EQ / тон','Компрессия / уровень','Сатурация / цвет','Фаза / стерео','Limiter / clipper']
    elif 'mix bus' in s or 'mastering' in s: wanted=['EQ / тон','Компрессия / уровень','Сатурация / цвет','Limiter / clipper','Контроль / анализ']
    else: wanted=['EQ / тон','Компрессия / уровень','Сатурация / цвет','Reverb / пространство']
    return [x for x in wanted if x in available]

def style_score(p,style,rank,is_main):
    text=' '.join([p['name'],p['developer'],p['category'],p['family'],p['kind'],p['description'],p['priority']]).casefold()
    score=rank+(0 if is_main else 18)
    if style=='clean':
        if any(x in text for x in ['чист','прозрач','clean','transparent','precision','точн']): score-=35
        if any(x in text for x in ['creative','fuzz','distortion','lo-fi','агрессив']): score+=25
        if p['priority']=='Основной': score-=18
    elif style=='character':
        if any(x in text for x in ['характер','analog','vintage','tube','tape','transformer','warm','color','агрессив','fet']): score-=38
        if 'чист' in text or 'transparent' in text: score+=12
    elif style=='fast':
        if p['priority']=='Быстрый workflow': score-=60
        if any(x in p['family'].casefold() for x in ['macro','chain','strip','finisher']): score-=35
        if p['priority']=='Основной': score-=10
    elif style=='creative':
        if p['priority']=='Уникальный / специальный': score-=60
        if 'creative' in p['category'].casefold(): score-=45
        if any(x in text for x in ['granular','lo-fi','fuzz','cinematic','random','spectral','pitch','dark']): score-=30
        if is_main: score+=8
    else:
        if is_main: score-=30
        if p['priority']=='Основной': score-=20
    return score

def choose_for(taskrow,style):
    names=[n for n in taskrow['main']+taskrow['others'] if n in plugin_by_name]
    ranked=sorted(names,key=lambda n:style_score(plugin_by_name[n],style,names.index(n),n in taskrow['main']))
    return ranked[0] if ranked else None, ranked[1] if len(ranked)>1 else None

