def recommendation_bucket(p):
    text=' '.join([p['name'],p['category'],p['family'],p['kind'],p['description'],p['priority']]).casefold()
    if p['priority']=='Быстрый workflow' or any(x in p['family'].casefold() for x in ['macro','chain','strip','finisher']): return 'fast'
    if any(x in text for x in ['analog','vintage','tube','tape','transformer','характер','color','fuzz','distortion','warm']): return 'character'
    if p['priority']=='Основной' or any(x in text for x in ['чист','clean','transparent','precision','прозрач']): return 'clean'
    return 'other'

