# Search is built after guide enrichment so Russian explanations, Controls,
# source-aware settings and analogue notes are discoverable. Store unique
# tokens rather than duplicated prose to keep the autonomous HTML compact.
def _search_values(value):
    if isinstance(value, str):
        yield value
    elif isinstance(value, dict):
        for nested in value.values():
            yield from _search_values(nested)
    elif isinstance(value, (list, tuple)):
        for nested in value:
            yield from _search_values(nested)

_search_token=re.compile(r'[0-9a-zа-яё]+(?:[./+_-][0-9a-zа-яё]+)*',re.IGNORECASE)
for p in plugins:
    searchable={
        'catalog':[p['name'],p['developer'],p['category'],p['family'],p['kind'],p['where'],p['description'],p['priority']],
        'uses':p['uses'],'analogues':p['analogues'],'guide':p['guide'],
    }
    tokens=[]
    for text in _search_values(searchable):
        tokens.extend(_search_token.findall(text.casefold()))
    p['search']=' '.join(dict.fromkeys(tokens))

